package org.example.service;import org.example.entity.Employee;import org.example.repository.EmployeeRepo;import org.springframework.stereotype.Service;import java.util.List;@Servicepublic class EmpServiceImp {    private final EmployeeRepo emprepo;    public EmpServiceImp(EmployeeRepo emprepo) {        this.emprepo = emprepo;    }    public String addEmp() {        Employee emp = new Employee(                200,                "Rahul",                "SD",                "rahul@gmail.com",                "Java"        );        return emprepo.addEmp(emp);    }    public Employee getEmpbyId(long emp_id) {        return emprepo.getEmpbyId(emp_id);    }    public List<Employee> getEmp() {        return emprepo.getEmp();    }}